package com.gerenciadorrural.modules.finance.application;
import com.gerenciadorrural.modules.finance.domain.*; import com.gerenciadorrural.shared.tenancy.*; import org.springframework.stereotype.Service; import java.math.*; import java.time.*; import java.util.*; import static com.gerenciadorrural.modules.finance.domain.FinanceModels.*;
@Service public class FinanceService {private final TenantTransactionExecutor tx;private final FinanceRepository repo;private final Clock clock;private static final Set<String> CATEGORY_WRITE=Set.of("OWNER","ADMIN","MANAGER"), ENTRY_WRITE=Set.of("OWNER","ADMIN","MANAGER","OPERATOR");public FinanceService(TenantTransactionExecutor tx,FinanceRepository repo,Clock clock){this.tx=tx;this.repo=repo;this.clock=clock;}
 public Category createCategory(TenantContext c,String name,String code,CategoryKind kind){categoryWrite(c);if(kind==null)throw new Invalid();Category x=new Category(UUID.randomUUID(),text(name,120),nullable(code,60),kind,CategoryStatus.ACTIVE,0,null,null);return tx.execute(c,()->repo.insertCategory(c.tenantId(),x));} public List<Category> categories(TenantContext c){return tx.execute(c,()->repo.categories(c.tenantId()));}public Category category(TenantContext c,UUID id){return tx.execute(c,()->repo.category(c.tenantId(),id,false).orElseThrow(CategoryNotFound::new));}
 public Category patchCategory(TenantContext c,UUID id,Long v,String name,boolean hn,String code,boolean hc,CategoryKind kind,boolean hk,CategoryStatus status,boolean hs){categoryWrite(c);if(v==null||v<0||(hn&&name==null)||(hk&&kind==null)||(hs&&status==null))throw new Invalid();return tx.execute(c,()->{Category x=repo.category(c.tenantId(),id,true).orElseThrow(CategoryNotFound::new);Category n=new Category(id,hn?text(name,120):x.name(),hc?nullable(code,60):x.code(),hk?kind:x.kind(),hs?status:x.status(),x.version(),x.createdAt(),x.updatedAt());if(same(x,n))return x;return repo.updateCategory(c.tenantId(),n,v);});}
 public Entry create(TenantContext c,UUID op,EntryType type,UUID category,String description,BigDecimal amount,LocalDate due,String notes){entryWrite(c);Valid q=valid(op,type,category,description,amount,due,notes);return tx.execute(c,()->{repo.lockOperation(c.tenantId(),c.farmId(),op);Entry old=repo.entryByOperation(c.tenantId(),c.farmId(),op).orElse(null);if(old!=null){if(!canonical(old).equals(canonical(q)))throw new Idempotency();return old;}Category cat=repo.category(c.tenantId(),category,true).orElseThrow(CategoryNotFound::new);compatible(cat,type);Entry x=new Entry(UUID.randomUUID(),op,type,EntryStatus.PENDING,new CategorySummary(cat.id(),cat.name(),cat.kind()),q.description,q.amount,q.due,null,q.notes,0,null,null);Entry saved=repo.insertEntry(c.tenantId(),c.farmId(),x,c.userId());repo.event(c.tenantId(),c.farmId(),saved.id(),op,EventType.CREATED,c.userId(),due,Map.of("type",type.name(),"amount",amount));return saved;});}
 public Entry patch(TenantContext c,UUID id,Long v,UUID category,boolean hc,String desc,boolean hd,BigDecimal amount,boolean ha,LocalDate due,boolean hdu,String notes,boolean hn){entryWrite(c);if(v==null||v<0||(hc&&category==null)||(hd&&desc==null)||(ha&&amount==null)||(hdu&&due==null))throw new Invalid();return tx.execute(c,()->{Entry x=repo.entry(c.tenantId(),c.farmId(),id,true).orElseThrow(EntryNotFound::new);if(x.status()!=EntryStatus.PENDING)throw new Conflict();CategorySummary cs=x.category();if(hc){Category cat=repo.category(c.tenantId(),category,true).orElseThrow(CategoryNotFound::new);compatible(cat,x.type());cs=new CategorySummary(cat.id(),cat.name(),cat.kind());}Entry n=new Entry(x.id(),x.operationId(),x.type(),x.status(),cs,hd?text(desc,240):x.description(),ha?money(amount):x.amount(),hdu?due:x.dueOn(),x.settledOn(),hn?nullable(notes,2000):x.notes(),x.version(),x.createdAt(),x.updatedAt());if(same(x,n))return x;Entry saved=repo.updateEntry(c.tenantId(),c.farmId(),n,v,c.userId());repo.event(c.tenantId(),c.farmId(),id,null,EventType.CORRECTED,c.userId(),null,Map.of("version",saved.version()));return saved;});}
 public Entry settle(TenantContext c,UUID id,UUID op,Long v,LocalDate date){entryWrite(c);if(op==null||v==null||v<0||date==null)throw new Invalid();return transition(c,id,op,v,date,null,EntryStatus.SETTLED);}public Entry cancel(TenantContext c,UUID id,UUID op,Long v,String reason){entryWrite(c);if(op==null||v==null||v<0)throw new Invalid();return transition(c,id,op,v,null,nullable(reason,2000),EntryStatus.CANCELLED);}
 private Entry transition(TenantContext c,UUID id,UUID op,Long v,LocalDate date,String reason,EntryStatus target){return tx.execute(c,()->{repo.lockOperation(c.tenantId(),c.farmId(),op);Event old=repo.eventByOperation(c.tenantId(),c.farmId(),id,op).orElse(null);Entry x=repo.entry(c.tenantId(),c.farmId(),id,true).orElseThrow(EntryNotFound::new);if(x.operationId().equals(op))throw new Idempotency();if(old!=null){String expected=target==EntryStatus.SETTLED?String.valueOf(date):String.valueOf(reason);if(!String.valueOf(old.details()).contains(expected))throw new Idempotency();return x;}if(x.status()!=EntryStatus.PENDING)throw new Conflict();Entry n=new Entry(x.id(),x.operationId(),x.type(),target,x.category(),x.description(),x.amount(),x.dueOn(),target==EntryStatus.SETTLED?date:null,x.notes(),x.version(),x.createdAt(),x.updatedAt());Entry saved=repo.updateEntry(c.tenantId(),c.farmId(),n,v,c.userId());Object details=target==EntryStatus.SETTLED?Map.of("settledOn",date.toString()):Map.of("reason",reason==null?"":reason);repo.event(c.tenantId(),c.farmId(),id,op,target==EntryStatus.SETTLED?EventType.SETTLED:EventType.CANCELLED,c.userId(),date,details);return saved;});}
 public Entry entry(TenantContext c,UUID id){return tx.execute(c,()->repo.entry(c.tenantId(),c.farmId(),id,false).orElseThrow(EntryNotFound::new));} public List<Event> history(TenantContext c,UUID id){return tx.execute(c,()->{entry(c,id);return repo.history(c.tenantId(),c.farmId(),id);});}public Page<Entry> entries(TenantContext c,EntryType t,EntryStatus s,UUID cat,LocalDate f,LocalDate to,String q,int page,int size){query(f,to,page,size);return tx.execute(c,()->{long total=repo.count(c.tenantId(),c.farmId(),t,s,cat,f,to,q);return new Page<>(repo.entries(c.tenantId(),c.farmId(),t,s,cat,f,to,q,size,(long)page*size),page,size,total,Math.toIntExact((total+size-1)/size));});}public Summary summary(TenantContext c,UUID cat,LocalDate f,LocalDate to){query(f,to,0,1);return tx.execute(c,()->repo.summary(c.tenantId(),c.farmId(),cat,f,to,LocalDate.now(clock)));}public List<CategoryTotals> categoryTotals(TenantContext c,LocalDate f,LocalDate to){query(f,to,0,1);return tx.execute(c,()->repo.categoryTotals(c.tenantId(),c.farmId(),f,to));}
 private Valid valid(UUID op,EntryType type,UUID category,String d,BigDecimal a,LocalDate due,String n){if(op==null||type==null||category==null||due==null)throw new Invalid();return new Valid(op,type,category,text(d,240),money(a),due,nullable(n,2000));}private record Valid(UUID op,EntryType type,UUID category,String description,BigDecimal amount,LocalDate due,String notes){}private static BigDecimal money(BigDecimal x){if(x==null||x.signum()<=0||x.scale()>2||x.precision()>19)throw new Invalid();return x;}private static String text(String x,int max){if(x==null)throw new Invalid();String y=x.strip();if(y.isBlank()||y.indexOf('\0')>=0||y.codePointCount(0,y.length())>max)throw new Invalid();return y;}private static String nullable(String x,int max){if(x==null)return null;String y=x.strip();if(y.isEmpty())return null;if(y.indexOf('\0')>=0||y.codePointCount(0,y.length())>max)throw new Invalid();return y;}private static void compatible(Category c,EntryType t){if(c.status()!=CategoryStatus.ACTIVE||(c.kind()!=CategoryKind.BOTH&&!c.kind().name().equals(t.name())))throw new Conflict();}private static void query(LocalDate f,LocalDate t,int p,int s){if(f==null||t==null||f.isAfter(t)||p<0||s<1||s>100)throw new Invalid();}private static void categoryWrite(TenantContext c){if(!CATEGORY_WRITE.contains(c.role()))throw new Forbidden();}private static void entryWrite(TenantContext c){if(!ENTRY_WRITE.contains(c.role()))throw new Forbidden();}private static boolean same(Category a,Category b){return a.name().equals(b.name())&&Objects.equals(a.code(),b.code())&&a.kind()==b.kind()&&a.status()==b.status();}private static boolean same(Entry a,Entry b){return a.category().id().equals(b.category().id())&&a.description().equals(b.description())&&a.amount().compareTo(b.amount())==0&&a.dueOn().equals(b.dueOn())&&Objects.equals(a.notes(),b.notes());}private static String canonical(Entry x){return x.type()+"|"+x.category().id()+"|"+x.description()+"|"+x.amount().stripTrailingZeros()+"|"+x.dueOn()+"|"+Objects.toString(x.notes(),"");}private static String canonical(Valid x){return x.type+"|"+x.category+"|"+x.description+"|"+x.amount.stripTrailingZeros()+"|"+x.due+"|"+Objects.toString(x.notes,"");} public record Page<T>(List<T> items,int page,int size,long totalElements,int totalPages){}public static class Invalid extends RuntimeException{}public static class Forbidden extends RuntimeException{}public static class CategoryNotFound extends RuntimeException{}public static class EntryNotFound extends RuntimeException{}public static class Conflict extends RuntimeException{}public static class Idempotency extends RuntimeException{} }
